<script setup>
import {ref,onMounted} from 'vue'
import {useRoute} from 'vue-router'
import {Star,ArrowLeft} from 'lucide-vue-next'
import {api} from '../api'
const route=useRoute(),records=ref([]),page=ref(1),total=ref(0),loading=ref(true),error=ref(''),success=ref(''),order=ref(null),rating=ref(5),content=ref(''),saving=ref(false)
async function load(){loading.value=true;error.value='';try{const d=await api('/reviews',{query:{page:page.value,pageSize:12}});records.value=d.records;total.value=d.total}catch(e){error.value=e.message}finally{loading.value=false}}
async function submit(){saving.value=true;error.value='';try{await api('/reviews',{method:'POST',body:{orderId:order.value.id,rating:rating.value,content:content.value}});order.value=null;success.value='评价已提交';page.value=1;await load()}catch(e){error.value=e.message}finally{saving.value=false}}
onMounted(async()=>{await load();if(route.query.orderId){try{const d=await api('/orders/'+route.query.orderId);if(d.status!=='COMPLETED')throw new Error('仅已归还订单可评价');order.value=d}catch(e){error.value=e.message}}})
</script>
<template><section class="wrap member-list-page"><RouterLink to="/me" class="back-link"><ArrowLeft :size="16"/>我的</RouterLink><header class="member-page-heading"><h1>历史评价</h1><p class="muted">记录真实的租赁体验，每笔已归还订单可评价一次。</p></header><p v-if="error" role="alert" class="alert error">{{error}}</p><p v-if="success" role="status" class="alert success">{{success}}</p><form v-if="order" class="review-form panel" @submit.prevent="submit"><h2>评价 {{order.equipmentName}}</h2><label>评分<select v-model.number="rating" :disabled="saving"><option v-for="n in [5,4,3,2,1]" :key="n" :value="n">{{n}} 星</option></select></label><label>租赁体验<textarea v-model="content" maxlength="500" required :disabled="saving" placeholder="说说器材状态、使用体验或交接感受"/></label><button class="button" :disabled="saving">{{saving?'提交中…':'提交评价'}}</button></form><div v-if="loading" class="state">正在读取评价…</div><div v-else-if="!records.length&&!error" class="state panel"><Star :size="35"/><h3>暂无历史评价</h3><p>完成租赁并归还后，可从订单详情提交评价。</p><RouterLink class="button small" to="/orders">查看全部订单</RouterLink></div><div v-else class="review-list"><article v-for="item in records" :key="item.id" class="review-card panel"><div><h2>{{item.equipmentName}}</h2><span :aria-label="item.rating+'星'">{{'★'.repeat(item.rating)}}{{'☆'.repeat(5-item.rating)}}</span></div><p>{{item.content}}</p><footer><time>{{item.createdAt}}</time><RouterLink :to="{path:'/orders',query:{id:item.orderId}}">查看订单 →</RouterLink></footer></article></div><div v-if="total>12" class="pagination"><button :disabled="page===1||loading" @click="page--;load()">上一页</button><span>{{page}} / {{Math.ceil(total/12)}}</span><button :disabled="page*12>=total||loading" @click="page++;load()">下一页</button></div></section></template>
